const NeuroConnections = (() => {
    const e = hubUtils.escapeHtml, u = hubUtils.sourceHref, d = neuroConnectionsData, o = neuroOriginsData;
    const node = (id) => d.nodes.find(n => n.id === id), edge = (id) => d.edges.find(x => x.id === id);
    const company = (id) => o.companies.find(c => c.id === id || c.nodeId === id);
    const link = (view, id = '', params = {}) => '#connections' + (id ? '/' + encodeURIComponent(id) : '') + '?' + new URLSearchParams({ view, ...params }).toString();
    const nav = (view) => `<nav class="or-tabs" aria-label="Research connection views">${[['origins', 'Company origins'], ['families', 'Technology families'], ['network', 'Explore the network'], ['coverage', 'Coverage & sources']].map(([id, name]) => `<a data-or-nav href="${e(link(id))}"${id === view ? ' aria-current="page"' : ''}>${name}</a>`).join('')}</nav>`;
    function evidenceButton(id, label = 'Evidence ↗') { const x = edge(id); return x ? `<button type="button" class="or-evidence-link" data-or-evidence="${e(id)}" aria-label="Evidence: ${e(node(x.from).name + ' ' + x.label + ' ' + node(x.to).name)}">${e(label)}</button>` : ''; }
    function evidenceLinks(ids) { return `<div class="or-evidence-links">${ids.filter(id => edge(id)).map((id, i) => evidenceButton(id, ids.length > 1 ? 'Source ' + (i + 1) + ' ↗' : 'Read the evidence ↗')).join('')}</div>`; }
    function sourceLinks(sources = []) { return sources.length ? `<details class="or-step-sources"><summary>Original sources (${sources.length})</summary>${sources.map(s => `<a href="${u(s.url)}" target="_blank" rel="noopener noreferrer">${e(s.title)} ↗</a>`).join('')}</details>` : ''; }
    function photo(c, mini = false) { const n = node(c.nodeId), m = n?.media ? NeuroVisuals.items().find(m => m.id === n.media) : null; if (!m)
        return `<div class="or-placeholder" data-family="${e(c.family)}" aria-hidden="true">${device(c.family)}<span>Interface schematic</span></div>`; return mini ? `<div class="or-card-photo">${NeuroVisuals.picture(m)}</div>` : `<figure class="or-photo"><button type="button" data-visual-open="${e(m.id)}" aria-label="Enlarge image: ${e(m.title)}">${NeuroVisuals.picture(m)}<span>View image ⤢</span></button>${NeuroVisuals.credit(m)}</figure>`; }
    function device(id) { const surface = ['surface', 'vascular'].includes(id), sensory = id === 'sensory', wireless = id === 'stimulation'; return `<svg viewBox="0 0 240 130" focusable="false" aria-hidden="true"><path d="M18 99Q55 72 92 96T167 94T223 93" fill="none" stroke="currentColor" opacity=".3" stroke-width="2"/>${surface ? `<path d="${id === 'vascular' ? 'M38 75Q97 13 200 76' : 'M38 79Q107 59 200 79'}" fill="none" stroke="currentColor" stroke-width="12" opacity=".25"/>${[60, 84, 108, 132, 156, 180].map((x, i) => `<circle cx="${x}" cy="${id === 'vascular' ? 53 + Math.abs(2.5 - i) * 8 : 72}" r="4" fill="currentColor"/>`).join('')}` : sensory ? '<path d="M66 86Q18 54 65 27Q105 15 129 52Q153 81 183 64" fill="none" stroke="currentColor" stroke-width="4"/><circle cx="82" cy="55" r="18" fill="none" stroke="currentColor" stroke-width="2"/><path d="M135 56h60m-9-7 9 7-9 7" stroke="currentColor" fill="none"/>' : wireless ? '<rect x="83" y="44" width="72" height="48" rx="12" fill="currentColor" opacity=".3"/><path d="M79 36Q120 4 162 36m-71-9q28-22 57 0M99 73h9l7-20 9 29 7-16h13" fill="none" stroke="currentColor" stroke-width="2"/>' : `${[75, 105, 135, 165].map(x => `<path d="M${x} 28v67" stroke="currentColor" stroke-width="${id === 'flexible' ? 2 : 7}"/>${[64, 76, 88].map(y => `<circle cx="${x}" cy="${y}" r="3" fill="#f7fbfa"/>`).join('')}`).join('')}<path d="M66 28h108" stroke="currentColor" stroke-width="14"/>`}</svg>`; }
    function header(view) { return `<header class="or-head"><div><span class="eyebrow">THE ORIGINS ATLAS</span><h1>Where the technology<br><em>comes from.</em></h1><p>Follow an idea from research to a company and the interface it builds.</p></div><div class="or-head-count"><strong>${o.companies.length}</strong><span>company histories</span><small>${d.edges.length} evidence-linked relationships</small></div></header>${nav(view)}`; }
    function companyCard(c) { return `<a class="or-company-card" data-or-nav href="${e(link('origins', c.id))}">${photo(c, true)}<div><span class="or-family-label">${e(o.families.find(f => f.id === c.family)?.name || c.family)}</span><h2>${e(c.name)} <b>↗</b></h2><p>${e(c.summary)}</p><span class="or-card-bottom">${c.timeline.length} milestones <i>·</i> ${c.edgeIds.length} relationships</span></div></a>`; }
    function directory(params) { const q = params.get('q') || '', family = params.get('family') || ''; const filtered = o.companies.filter(c => (!family || c.family === family) && hubUtils.matches(c.name + ' ' + c.summary + ' ' + c.stages.map(s => s.title + ' ' + s.text).join(' ') + ' ' + c.edgeIds.map(id => { const x = edge(id); return x ? node(x.from)?.name + ' ' + x.label + ' ' + node(x.to)?.name + ' ' + x.detail : ''; }).join(' '), q)); return `${header('origins')}<section class="or-start"><div><span class="eyebrow">A CLEARER WAY TO FOLLOW THE FIELD</span><h2>One company. Three questions.</h2></div><div class="or-three-questions"><span><b>01</b>Where did it start?</span><i>→</i><span><b>02</b>How did it move into a company?</span><i>→</i><span><b>03</b>What did they build?</span></div></section><form id="or-filter" class="or-filter" role="search"><label><span class="sr-only">Find a company or research origin</span><input id="or-query" name="q" type="search" placeholder="Company, person, lab, or earlier technology…" value="${e(q)}"></label><label><span class="sr-only">Technology family</span><select id="or-family" name="family"><option value="">All technology families</option>${o.families.map(f => `<option value="${e(f.id)}"${family === f.id ? ' selected' : ''}>${e(f.name)}</option>`).join('')}</select></label><button type="submit">Find</button></form><div class="or-results"><span role="status">${filtered.length} company ${filtered.length === 1 ? 'history' : 'histories'}</span><a href="${e(link('coverage'))}" data-or-nav>What has been checked? ↗</a></div><div class="or-company-grid">${filtered.map(companyCard).join('') || `<div class="hub-empty"><h2>No matching histories.</h2><a data-or-nav href="${e(link('origins'))}">Clear filters →</a></div>`}</div>`; }
    function chips(ids) { return `<div class="or-entity-chips">${ids.filter(id => node(id)).map(id => `<a data-or-nav href="${e(link('network', id))}"><span>${e(node(id).kind)}</span>${e(node(id).name)} ↗</a>`).join('')}</div>`; }
    function companyPage(c) { const family = o.families.find(f => f.id === c.family); const related = o.companies.filter(x => x.id !== c.id && x.family === c.family); return `${nav('origins')}<a class="or-back" data-or-nav href="${e(link('origins'))}">← All company histories</a><header class="or-company-head"><div><span class="eyebrow">${e(family?.name || c.family)} · ORIGIN STORY</span><h1>${e(c.name)}</h1><p>${e(c.summary)}</p><div class="or-company-actions"><a data-or-nav href="${e(link('network', c.nodeId))}">Explore its full network ↗</a><a href="#org/${e(c.id)}">Company profile ↗</a></div></div>${photo(c)}</header><section class="or-lineage" aria-label="Research roots, company formation, and interface"><div class="or-lineage-heading"><h2>Follow the origin story</h2><span>Follow the numbered stages · not a time scale</span></div><div class="or-stage-grid">${c.stages.map((s, i) => `<article class="or-stage"><span class="or-stage-number">0${i + 1}</span><span class="eyebrow">${['RESEARCH ROOTS', 'TRANSLATION', 'INTERFACE BUILT'][i] || 'NEXT STEP'}</span><h3>${e(s.title)}</h3><p>${e(s.text)}</p>${chips(s.nodes)}${evidenceLinks(s.edges)}${sourceLinks(s.sources)}</article>`).join('')}</div></section><div class="or-history-layout"><section class="or-timeline"><span class="eyebrow">HOW THE WORK DEVELOPED</span><h2>The milestones that connect it</h2><ol>${c.timeline.map(t => `<li><div class="or-timeline-date">${e(t.date)}</div><div><h3>${e(t.title)}</h3><p>${e(t.text)}</p>${evidenceLinks(t.edges)}${sourceLinks(t.sources)}</div></li>`).join('')}</ol></section><aside class="or-engineering"><span class="eyebrow">THE ENGINEERING IDEA</span><h2>What changed along the way?</h2>${c.changes.map(x => `<article><h3>${e(x.title)}</h3><p>${e(x.text)}</p>${evidenceLinks(x.edges)}${sourceLinks(x.sources)}</article>`).join('')}<details class="or-gaps"><summary>What is still uncertain?</summary>${c.gaps.length ? c.gaps.map(g => `<p>${e(g)}</p>`).join('') : '<p>No additional gaps are listed for this selected account. It remains a curated history, not an exhaustive record.</p>'}</details></aside></div><section class="or-crosslinks"><div><span class="eyebrow">FOLLOW A DIFFERENT BRANCH</span><h2>Related technical approaches</h2><p>These companies share a broad design area. Their individual histories establish whether there is an actual transfer or collaboration.</p></div><div>${related.slice(0, 6).map(x => `<a data-or-nav href="${e(link('origins', x.id))}">${e(x.name)} ↗</a>`).join('') || `<a data-or-nav href="${e(link('families'))}">Compare all technology families ↗</a>`}</div></section>${relationshipList(c.edgeIds, 'All relationships in this history')}${sourceLinks(c.sources)}`; }
    function relationshipList(ids, title) { return `<details class="or-relationship-list"><summary>${e(title)} <span>${ids.length}</span></summary>${ids.map(id => { const x = edge(id); return x ? `<article><span>${x.basis === 'comparison' ? 'Technical comparison' : e(x.date)}</span><p><strong>${e(node(x.from).name)}</strong> ${e(x.label)} <strong>${e(node(x.to).name)}</strong></p>${evidenceButton(id)}</article>` : ''; }).join('')}</details>`; }
    function families() { return `${header('families')}<p class="or-family-intro">Start with the engineering problem. Each branch groups approaches with a similar interface; it does not imply that one company descended from another.</p><div class="or-family-tree">${o.families.map(f => { const cs = o.companies.filter(c => c.family === f.id); return `<section class="or-family-row"><div class="or-family-root">${device(f.id)}<div><span class="eyebrow">${cs.length} company histories</span><h2>${e(f.name)}</h2><p>${e(f.description)}</p></div></div><div class="or-family-branches">${cs.map(c => `<a data-or-nav href="${e(link('origins', c.id))}"><strong>${e(c.name)}</strong><span>${e(c.stages[2]?.title || c.summary)} ↗</span></a>`).join('')}</div></section>`; }).join('')}</div><a class="or-wide-link" data-or-nav href="${e(link('network'))}">Look for documented connections between these branches ↗</a>`; }
    function coverage() { const reviewed = new Set(o.companies.map(c => c.id)); const counts = { reviewed: o.inventory.filter(c => reviewed.has(c.id)).length, total: o.inventory.length, scope: o.inventory.filter(c => c.scope === 'implant').length }; return `${header('coverage')}<section class="or-coverage-summary"><h2>A visible research ledger.</h2><p>${counts.total} companies are indexed in the wider atlas. This release investigates ${counts.scope} entries flagged for implanted interfaces and related hardware. ${counts.reviewed} have origin dossiers here. The remaining wider-atlas companies cover other parts of neuroengineering.</p><p>Each history distinguishes evidence of origin, a later collaboration, a shared method, and gaps that could not be resolved. A checked company may still have an unknown founding or training history.</p></section><div class="or-method-grid"><section><h2>How connections enter the map</h2><ol><li>Start from the company’s technology and founders.</li><li>Read university histories, original papers, lab rosters and company records.</li><li>Separate explicit development or licensing from similar designs.</li><li>Preserve conflicting dates and missing evidence in the company history.</li></ol></section><section><h2>Reusable data and tools</h2><p>The interactive network uses <a href="https://js.cytoscape.org/" target="_blank" rel="noopener noreferrer">Cytoscape.js ↗</a>. Its graph data can be imported into other Cytoscape tools. Crossref metadata adds bibliographic context; citations alone do not establish mentorship or technology transfer.</p><div class="or-downloads"><a href="./data/connections.json" download>Relationships JSON ↓</a><a href="./data/company-origins.json" download>Company histories JSON ↓</a><a href="./downloads/connections.cy.json" download>Cytoscape graph ↓</a><a href="./data/connection-papers.json" download>Paper metadata ↓</a></div></section></div><section class="or-paper-library"><span class="eyebrow">BIBLIOGRAPHIC CONTEXT</span><h2>${o.papers?.length || 0} paper records imported from Crossref</h2><p>Open the original paper or download its reference metadata. These citation records are separate from the curated historical relationships.</p><details><summary>Browse the research papers</summary><div>${(o.papers || []).map(p => `<a href="${u(p.url)}" target="_blank" rel="noopener noreferrer"><span>${p.year || 'Undated'}</span><strong>${e(p.title)}</strong><small>${p.references.length} reference DOIs · ${e(p.doi)} ↗</small></a>`).join('')}</div></details></section><details class="or-coverage-table" open><summary>All ${counts.total} indexed companies · research status</summary><table><thead><tr><th>Company</th><th>Coverage</th><th>Explore</th></tr></thead><tbody>${o.inventory.map(c => `<tr><th scope="row">${e(c.name)}</th><td>${reviewed.has(c.id) ? 'Origin dossier available' : c.scope === 'implant' ? 'Origin research gap' : 'Wider atlas · not audited in this release'}</td><td><a href="${reviewed.has(c.id) ? e(link('origins', c.id)) : '#org/' + e(c.id)}">${reviewed.has(c.id) ? 'Read history' : 'Atlas profile'} ↗</a></td></tr>`).join('')}</tbody></table></details><p class="or-maintenance">Evidence reviewed ${e(o.reviewed)}. This is not a census of every company or an assertion that all historical connections have been found.</p>`; }
    function render(id = '', params = new URLSearchParams()) {
        const requested = params.get('view'), view = ['origins', 'families', 'network', 'coverage'].includes(requested || '') ? requested : id ? (company(id) && !params.has('edge') ? 'origins' : 'network') : 'origins';
        let body = '';
        if (view === 'origins')
            body = id ? (company(id) ? companyPage(company(id)) : `<h1>Company history not found.</h1><a href="${e(link('origins'))}">All company histories →</a>`) : directory(params);
        else if (view === 'families')
            body = families();
        else if (view === 'coverage')
            body = coverage();
        else
            body = `${nav('network')}${ConnectionNetwork.render(id, params)}`;
        return `<div class="or-page" data-or-view="${view}">${body}<dialog id="or-evidence-dialog" class="or-evidence-dialog" aria-label="Relationship evidence"><button class="or-dialog-close" type="button" data-or-close aria-label="Close relationship evidence">×</button><div id="or-evidence-content"></div></dialog></div>`;
    }
    let returnFocus = null;
    function close() { ConnectionNetwork.close(); const dialog = document.getElementById('or-evidence-dialog'); dialog?.close(); returnFocus = null; }
    function openEvidence(id, trigger) { const x = edge(id), dialog = document.getElementById('or-evidence-dialog'); if (!x || !dialog)
        return; returnFocus = trigger || document.activeElement; document.getElementById('or-evidence-content').innerHTML = ConnectionEvidence.evidence(x); dialog.showModal(); dialog.querySelector('[data-or-close]').focus(); }
    function bind(container, id, params, navigate) {
        container.querySelectorAll('[data-or-nav]').forEach(a => a.addEventListener('click', ev => { if (ev.metaKey || ev.ctrlKey || ev.shiftKey || ev.altKey)
            return; ev.preventDefault(); navigate(a.getAttribute('href')); window.scrollTo({ top: 0, behavior: 'instant' }); }));
        container.querySelectorAll('[data-or-evidence]').forEach(b => b.addEventListener('click', () => openEvidence(b.dataset.orEvidence, b)));
        const dialog = container.querySelector('#or-evidence-dialog');
        dialog?.querySelector('[data-or-close]')?.addEventListener('click', () => dialog.close());
        dialog?.addEventListener('close', () => { returnFocus?.focus({ preventScroll: true }); returnFocus = null; });
        dialog?.addEventListener('click', ev => { if (ev.target === dialog)
            dialog.close(); });
        container.querySelector('#or-filter')?.addEventListener('submit', ev => { ev.preventDefault(); const q = container.querySelector('#or-query').value.trim(), family = container.querySelector('#or-family').value; navigate(link('origins', '', { ...(q ? { q } : {}), ...(family ? { family } : {}) }), 'or-query'); });
        ConnectionNetwork.bind(container, id, params, navigate, openEvidence);
    }
    function teaser(profileHref) { const n = d.nodes.find(n => n.href === profileHref || n.aliases?.includes(profileHref)); if (!n)
        return ''; const c = company(n.id), count = ConnectionEvidence.incident(n.id).length; return `<a class="cn-teaser" href="${e(link(c ? 'origins' : 'network', c?.id || n.id))}"><span class="cn-teaser-icon" aria-hidden="true">○ → ◇ → ▦</span><span><small>ORIGINS &amp; CONNECTIONS</small><strong>${c ? 'Where ' + e(n.name) + '’s technology comes from' : 'Follow ' + e(n.name) + '’s research connections'}</strong><span>${count} direct relationships · inspect the original evidence</span></span><b aria-hidden="true">↗</b></a>`; }
    function spotlight() { return `<a class="cn-spotlight" href="#connections"><div><span class="eyebrow">THE ORIGINS ATLAS</span><h2>Every interface has a history.</h2><p>Follow ${o.companies.length} company stories from research roots to the technology they build.</p><strong>Explore origins &amp; connections ↗</strong></div><div class="cn-spotlight-path" aria-hidden="true"><span>Research roots</span><i>↓</i><span>Company</span><i>↓</i><span>Neural interface</span></div></a>`; }
    function records() { return d.nodes.map(n => ({ id: 'connection-' + n.id, title: n.name + ' — origins & connections', description: n.summary, kind: 'Research connection', href: link(company(n.id) ? 'origins' : 'network', company(n.id)?.id || n.id), keywords: n.subtitle + ' ' + ConnectionEvidence.incident(n.id).map(x => node(x.from).name + ' ' + x.label + ' ' + node(x.to).name).join(' ') })); }
    return { render, bind, close, records, teaser, spotlight, openEvidence, company, link, incident: ConnectionEvidence.incident };
})();
